return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30T15:26:17+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'Conectar cuentas de WordPress a Active Directory u OpenLDAP.','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','User data'=>'Datos del usuario','Single sign-on'=>'Inicio de sesión único','Custom user fields'=>'Campos de usuario personalizados','Copy LDAP attributes to WordPress user meta fields.'=>'Copiar atributos LDAP a los campos de meta del usuario de WordPress.','Field mappings'=>'Mapeo de campos','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'Una asignación por línea: atributo LDAP:clave meta de WordPress:tipo. Ejemplo: %1$s. Tipos: %2$s o %3$s.','Custom field storage'=>'Almacenamiento de campos personalizados','Leave the defaults unless your integration uses different user meta keys.'=>'Deje los valores predeterminados a menos que su integración use claves de meta de usuario diferentes.','LDAP value suffix'=>'Sufijo de valor LDAP','Stores the LDAP value, such as phone_ldap.'=>'Almacena el valor LDAP, como phone_ldap.','WordPress value suffix'=>'Sufijo de valor de WordPress','Stores the editable WordPress value, such as phone_wp.'=>'Almacena el valor editable de WordPress, como phone_wp.','Single sign-on (SSO)'=>'Inicio de sesión único (SSO)','Your web server must authenticate users and set REMOTE_USER. Never copy a browser header into REMOTE_USER or allow access that bypasses server authentication. Set the LDAP search account on Connection.'=>'Su servidor web debe autenticar a los usuarios y establecer REMOTE_USER. Nunca copie un encabezado del navegador en REMOTE_USER ni permita acceso que eluda la autenticación del servidor. Establezca la cuenta de búsqueda LDAP en Conexión.','Enable automatic login after web server authentication.'=>'Habilitar inicio de sesión automático después de la autenticación del servidor web.','Web server authentication'=>'Autenticación del servidor web','REMOTE_USER is present.'=>'REMOTE_USER está presente.','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER está ausente. Verifique la configuración del servidor web.','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'La actualización fue detenida. Activa Simple LDAP Login Pro para restaurar el inicio de sesión LDAP.','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'Actualización bloqueada: Este paquete no incluye todos los archivos Pro. Para instalar Free, desactiva el plugin primero. Tus archivos y configuraciones instalados permanecen sin cambios.','WordPress could not reactivate the plugin.'=>'WordPress no pudo reactivar el plugin.','Simple LDAP Login needs PHP 8.1 or later.'=>'Simple LDAP Login necesita PHP 8.1 o superior.','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'Faltan archivos del plugin. Reinstale Simple LDAP Login desde el ZIP de lanzamiento.','You do not have permission to change these settings.'=>'No tiene permiso para cambiar estas configuraciones.','The settings scope has changed. Open the settings page and try again.'=>'El alcance de la configuración ha cambiado. Abra la página de configuración y vuelva a intentarlo.','You do not have permission to view these settings.'=>'No tiene permiso para ver estas configuraciones.','Network settings'=>'Configuraciones de red','Site settings'=>'Configuraciones del sitio','LDAP login settings'=>'Configuraciones de inicio de sesión LDAP','Connect to LDAP, then test a login before enabling authentication.'=>'Conéctese a LDAP, luego pruebe un inicio de sesión antes de habilitar la autenticación.','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'El inicio de sesión LDAP y SSO están deshabilitados por SLL_DISABLE_LDAP en wp-config.php.','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'Tus configuraciones guardadas utilizan SSO o campos de usuario personalizados. Instala Simple LDAP Login Pro para usar estas funciones. Tus configuraciones se mantienen.','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'La contraseña de búsqueda LDAP guardada no se puede leer. Ingrésela nuevamente en la pestaña de Conexión.','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'Falta PHP LDAP. Pida a su proveedor que lo instale antes de habilitar el inicio de sesión LDAP.','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'Las contraseñas LDAP se envían sin cifrado. Use StartTLS o LDAPS si su servidor lo admite.','Save settings'=>'Guardar configuraciones','Settings on other tabs are kept.'=>'Las configuraciones en otras pestañas se mantienen.','LDAP connection'=>'Conexión LDAP','LDAP login'=>'Inicio de sesión LDAP','Enable LDAP authentication.'=>'Habilitar autenticación LDAP.','Directory type'=>'Tipo de directorio','Active Directory'=>'Active Directory','OpenLDAP / other LDAP directory'=>'OpenLDAP / otro directorio LDAP','LDAP servers'=>'Servidores LDAP','One hostname or IP address per line. Servers are tried in order.'=>'Un nombre de host o dirección IP por línea. Se probarán los servidores en orden.','Base DN'=>'Base DN','Where to search for users. Example: DC=example,DC=org.'=>'Dónde buscar usuarios. Ejemplo: DC=example,DC=org.','Username suffix'=>'Sufijo de nombre de usuario','Added to usernames without a domain. Example: @example.org.'=>'Añadido a nombres de usuario sin un dominio. Ejemplo: @example.org.','Windows domain'=>'Dominio de Windows','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'Nombre de dominio corto, como EXAMPLE. Tiene prioridad sobre el sufijo de nombre de usuario.','Connection security'=>'Seguridad de conexión','TLS requires a trusted server certificate.'=>'TLS requiere un certificado de servidor de confianza.','StartTLS (recommended)'=>'StartTLS (recomendado)','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'LDAP sin cifrado','Unencrypted LDAP requires permission on the Advanced tab.'=>'LDAP sin cifrado requiere permiso en la pestaña Avanzado.','Port'=>'Puerto','389 for StartTLS; 636 for LDAPS.'=>'389 para StartTLS; 636 para LDAPS.','Search subfolders'=>'Buscar subcarpetas','Search all organizational units below the Base DN.'=>'Buscar todas las unidades organizativas debajo de la Base DN.','LDAP search account'=>'Cuenta de búsqueda LDAP','An LDAP account with read access to users and groups.'=>'Una cuenta LDAP con acceso de lectura a usuarios y grupos.','Search account'=>'Cuenta de búsqueda','LDAP bind DN or account name.'=>'DN de enlace LDAP o nombre de cuenta.','Search account password'=>'Contraseña de cuenta de búsqueda','Leave blank to keep the saved password.'=>'Deje en blanco para mantener la contraseña guardada.','Login rules'=>'Reglas de inicio de sesión','Require LDAP passwords'=>'Requerir contraseñas LDAP','Block WordPress passwords except for recovery access.'=>'Bloquear contraseñas de WordPress excepto para acceso de recuperación.','Local recovery access'=>'Acceso de recuperación local','Selected administrators'=>'Administradores seleccionados','All super administrators (legacy)'=>'Todos los superadministradores (legado)','All administrators (legacy)'=>'Todos los administradores (legado)','Off'=>'Desactivado','Choose who can use a WordPress password when LDAP passwords are required.'=>'Elija quién puede usar una contraseña de WordPress cuando se requieren contraseñas LDAP.','Automatic account creation'=>'Creación automática de cuentas','Create a WordPress account on the first successful LDAP login.'=>'Crear una cuenta de WordPress en el primer inicio de sesión LDAP exitoso.','Default role'=>'Rol predeterminado','For new accounts only.'=>'Solo para nuevas cuentas.','Required groups'=>'Grupos requeridos','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'Un nombre de grupo por línea. Los usuarios deben pertenecer a al menos uno. Deje en blanco para permitir todos los usuarios LDAP.','Recovery accounts'=>'Cuentas de recuperación','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'Solo para administradores seleccionados. Use cuentas locales separadas con contraseñas de WordPress. Mantenga presionado Ctrl o Command para seleccionar múltiples cuentas.','Connection options'=>'Opciones de conexión','Change these only if the default values do not work with your directory.'=>'Cambie esto solo si los valores predeterminados no funcionan con su directorio.','LDAP timeout (seconds)'=>'Tiempo de espera LDAP (segundos)','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'Tiempo máximo de espera para una operación LDAP. Predeterminado: 5 segundos.','Login attribute'=>'Atributo de inicio de sesión','Attribute used to find users. Default: uid.'=>'Atributo utilizado para encontrar usuarios. Predeterminado: uid.','Allow unencrypted LDAP'=>'Permitir LDAP sin cifrado','Allow passwords to be sent without encryption.'=>'Permitir que las contraseñas se envíen sin cifrado.','Group search'=>'Búsqueda de grupos','Group base DN'=>'DN base del grupo','Leave blank to use the user Base DN.'=>'Deje en blanco para usar el DN base del usuario.','Group name attribute'=>'Atributo del nombre del grupo','Default: cn.'=>'Predeterminado: cn.','Group member attribute'=>'Atributo de miembro del grupo','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'Predeterminado: memberUid. Use member o uniqueMember si los grupos almacenan DNs de usuario.','Profile attributes'=>'Atributos de perfil','LDAP attributes copied to new WordPress accounts.'=>'Atributos LDAP copiados a nuevas cuentas de WordPress.','First name attribute'=>'Atributo del nombre','Last name attribute'=>'Atributo del apellido','Email attribute'=>'Atributo del correo electrónico','Website attribute'=>'Atributo del sitio web','Data retention'=>'Retención de datos','Delete settings when removing the plugin'=>'Eliminar configuraciones al quitar el plugin','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'Eliminar configuraciones guardadas y credenciales LDAP cuando WordPress elimina el plugin. Mantener cuentas de usuario.','Test LDAP login'=>'Probar inicio de sesión LDAP','Save your settings, then run both tests. Keep this administrator session open.'=>'Guarde sus configuraciones, luego ejecute ambas pruebas. Mantenga esta sesión de administrador abierta.','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'Las pruebas verifican la conexión, la contraseña y los grupos requeridos. No crean cuentas ni inician sesión a los usuarios.','After both tests pass, enable LDAP and try logging in from another browser.'=>'Después de que ambas pruebas pasen, habilite LDAP e intente iniciar sesión desde otro navegador.','Recovery'=>'Recuperación','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'Si está bloqueado, cambie el nombre de la carpeta simple-ldap-login usando el administrador de archivos de su hosting. Inicie sesión con una contraseña de administrador de WordPress, luego restaure la carpeta y corrija las configuraciones.','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'Para errores de certificado, pida a su hosting que configure la autoridad de certificación LDAP de confianza.','LDAP tests'=>'Pruebas LDAP','Tests use saved settings.'=>'Las pruebas utilizan configuraciones guardadas.','1. Test connection'=>'1. Probar conexión','Connect to LDAP and test the search account, if set.'=>'Conéctese a LDAP y pruebe la cuenta de búsqueda, si está configurada.','Test connection'=>'Probar conexión','2. Test login'=>'2. Probar inicio de sesión','Check an LDAP username, password, and group membership.'=>'Verifique un nombre de usuario LDAP, contraseña y membresía de grupo.','LDAP username'=>'Nombre de usuario LDAP','LDAP password'=>'Contraseña LDAP','Settings saved.'=>'Configuraciones guardadas.','Connection test passed.'=>'Prueba de conexión aprobada.','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'No se puede conectar a LDAP. Verifique el servidor, puerto, certificado TLS y cuenta de búsqueda.','LDAP login test passed. No account was created.'=>'Prueba de inicio de sesión LDAP aprobada. No se creó ninguna cuenta.','LDAP login test failed. Check the username, password, and required groups.'=>'Prueba de inicio de sesión LDAP fallida. Verifique el nombre de usuario, contraseña y grupos requeridos.','Could not save settings. Check the values and try again.'=>'No se pudieron guardar las configuraciones. Verifique los valores y vuelva a intentarlo.','Connection'=>'Conexión','Access'=>'Acceso','Advanced'=>'Avanzado','Troubleshooting'=>'Solución de problemas','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'Su inicio de sesión LDAP es válido, pero necesita una cuenta de WordPress. Contacte a su administrador del sitio.','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'Su nombre de usuario LDAP no es un nombre de usuario de WordPress válido. Contacte a su administrador del sitio.','The default WordPress role is not available. Contact your site administrator.'=>'El rol predeterminado de WordPress no está disponible. Contacte a su administrador del sitio.','Could not create your WordPress account. Contact your site administrator.'=>'No se pudo crear su cuenta de WordPress. Contacte a su administrador del sitio.','Use your WordPress password for this recovery account.'=>'Use su contraseña de WordPress para esta cuenta de recuperación.','LDAP login failed. Check your username and password or contact your site administrator.'=>'El inicio de sesión LDAP falló. Verifique su nombre de usuario y contraseña o contacte a su administrador del sitio.','Your account is not allowed to log in to this site.'=>'Tu cuenta no está autorizada para iniciar sesión en este sitio.','LDAP login is unavailable. Contact your site administrator.'=>'El inicio de sesión LDAP no está disponible. Contacta a tu administrador del sitio.','PHP OpenSSL is required to save the LDAP search password.'=>'Se requiere PHP OpenSSL para guardar la contraseña de búsqueda LDAP.','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'No se pudo leer o guardar la contraseña de búsqueda LDAP. Introdúcela de nuevo. Si esto continúa, pide a tu proveedor que verifique OpenSSL y la clave de cifrado.','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'Selecciona una cuenta de recuperación en la pestaña Acceso, o desactiva el acceso de recuperación local.','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'Habilita Permitir LDAP sin cifrado en la pestaña Avanzado, o elige StartTLS o LDAPS.','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'Un mapeo de campo personalizado utiliza una clave de meta usuario de WordPress protegida o inválida.','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'Introduce un DN base y al menos un servidor LDAP antes de habilitar el inicio de sesión LDAP.','WordPress could not save the settings. Try again.'=>'WordPress no pudo guardar la configuración. Intenta de nuevo.','LDAP protocol version'=>'Versión del protocolo LDAP','LDAP timeout'=>'Tiempo de espera LDAP','Check the submitted settings. No changes were saved.'=>'Verifica la configuración enviada. No se guardaron cambios.','Check %s. No changes were saved.'=>'Verifica %s. No se guardaron cambios.']];